import{_ as t,m as d,k as o,ah as i}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"Authentication","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/development/authentication.md","filePath":"src/en/developers/development/authentication.md"}'),a={name:"developers/development/authentication.md"};function c(r,e,s,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Creopse relies on <a href="https://laravel.com/docs/sanctum" target="_blank" rel="noreferrer">Laravel Sanctum</a> for authentication, with two mechanisms depending on the client type:</p><ul><li><strong>Session/cookie</strong> for the admin interface (Inertia SPA) — the default mode for any &quot;browser&quot; request.</li><li><strong>Bearer token</strong> for external clients (mobile app, third-party integration) consuming the <a href="./api-endpoints.html">public API</a>.</li></ul><p>All authentication routes live under <code>/auth/*</code>; the rest of the API&#39;s protected routes use the <code>auth:sanctum</code> middleware, which accepts either mechanism indifferently.</p><h2 id="choosing-the-mode" tabindex="-1">Choosing the mode <a class="header-anchor" href="#choosing-the-mode" aria-label="Permalink to &quot;Choosing the mode&quot;">​</a></h2><p>The mode is determined automatically at login/registration, based on whether the <code>X-Client-Type: mobile</code> header (or <code>device_name</code>/<code>device_id</code> parameters) is present on the request:</p><ul><li><strong>Absent</strong> → session mode: <code>POST /auth/login</code> regenerates the session server-side, the cookie is authoritative for subsequent requests.</li><li><strong>Present</strong> → token mode: a Sanctum token is issued (<code>mobile</code> ability) and returned in the response as <code>token</code>, to be sent afterward via <code>Authorization: Bearer &lt;token&gt;</code>. Logging in again with the same <code>device_id</code> revokes the previous token.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the session cookie to work cross-origin (SPA on one domain, API on another), the domain must be listed in <code>SANCTUM_STATEFUL_DOMAINS</code> (<code>config/sanctum.php</code>) — by default only <code>localhost</code>/<code>127.0.0.1</code>. See also <a href="./api-endpoints.html#cors">CORS</a>.</p></div><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th><th>Access</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/auth/login</code></td><td>Login with email/username + password.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/register</code></td><td>Registration. The very first user created automatically receives the <code>super-admin</code> role.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/google</code></td><td>Login through a Google ID token.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/apple</code></td><td>Login through an Apple <code>identity_token</code>.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/phone</code></td><td>Sends a verification code by SMS.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/phone/verify</code></td><td>Validates the code sent, logs in.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/send-password-link</code></td><td>Sends a password reset link.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/reset-password</code></td><td>Resets the password using the received link.</td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-password</code></td><td>Changes the password (logged-in user).</td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-email</code></td><td>Changes the email — resets verification.</td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/auth/edit-username</code></td><td>Changes the username.</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/auth/send-verification-email</code></td><td>Resends the verification email.</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/auth/verify-email/{id}/{hash}</code></td><td>Validates the verification link (signed URL).</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/auth/logout/{guard?}</code></td><td>Logs out (revokes the token in mobile mode, invalidates the session otherwise).</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/auth/disable-account</code></td><td>Disables the current account (<code>account_status</code>), without deleting it.</td><td>Authenticated</td></tr><tr><td><code>GET</code></td><td><code>/auth/tokens/{name}</code></td><td>Lists the user&#39;s active tokens by name.</td><td>Authenticated</td></tr><tr><td><code>POST</code></td><td><code>/auth/tokens/revoke/{id}</code></td><td>Revokes a specific token.</td><td>Authenticated</td></tr></tbody></table><h2 id="logging-in-through-a-third-party-provider" tabindex="-1">Logging in through a third-party provider <a class="header-anchor" href="#logging-in-through-a-third-party-provider" aria-label="Permalink to &quot;Logging in through a third-party provider&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Mechanism</th></tr></thead><tbody><tr><td>Google</td><td>Verifies the ID token through the <code>Google\\Client</code> SDK (<code>GOOGLE_CLIENT_ID</code>/<code>GOOGLE_CLIENT_SECRET</code>/<code>GOOGLE_REDIRECT</code> in <code>config/services.php</code>).</td></tr><tr><td>Apple</td><td>Verifies the received <code>identity_token</code> JWT against Apple&#39;s public keys (JWKS).</td></tr><tr><td>Phone</td><td>Verification code sent through Twilio Verify (<code>TWILIO_SID</code>/<code>TWILIO_TOKEN</code>/<code>TWILIO_SERVICE</code>) or a configured alternative SMS provider.</td></tr></tbody></table><p>In all three cases, a user is automatically created if none exists yet (<code>auth_type</code> set accordingly), then logged in following the mode determined above.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>laravel/socialite</code> is listed among the package&#39;s dependencies but is <strong>not</strong> used by these integrations — Google/Apple/phone authentication is implemented directly, without going through Socialite.</p></div><h2 id="sessions-and-active-devices" tabindex="-1">Sessions and active devices <a class="header-anchor" href="#sessions-and-active-devices" aria-label="Permalink to &quot;Sessions and active devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/sessions</code></td><td>Unified list of active sessions: web sessions and Sanctum tokens (mobile), with the current device flagged.</td></tr><tr><td><code>DELETE</code></td><td><code>/sessions/{type}/{id}</code></td><td>Revokes a specific session or token (not possible for the current session).</td></tr><tr><td><code>DELETE</code></td><td><code>/sessions/revoke-all</code></td><td>Revokes every other session/token for the user.</td></tr></tbody></table><p>All of these routes require <code>auth:sanctum</code>.</p><h2 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h2><p>Access management relies on <a href="https://spatie.be/docs/laravel-permission" target="_blank" rel="noreferrer"><code>spatie/laravel-permission</code></a>. Four guards exist (<code>web</code>, <code>admin</code>, <code>api</code>, <code>mobile</code>); three default roles are provided (<code>super-admin</code>, <code>admin</code>, <code>user</code>), each with a default permission set. See <a href="./../admin-panel/user-role-management.html">User &amp; Role Management</a> for the admin interface equivalent.</p><p><code>GET /roles</code> and <code>GET /permissions</code> are public; creating/editing/deleting roles and permissions requires <code>auth:sanctum</code>. Some user management actions (<code>POST /users</code>, <code>PUT /users/{user}</code>, <code>DELETE /users/{user}</code>...) additionally require a specific named permission (<code>action-add-user</code>, <code>action-edit-user</code>, <code>action-delete-user</code>...).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Content</th></tr></thead><tbody><tr><td><code>config/auth.php</code></td><td>Guards (<code>web</code>, <code>admin</code>), providers, user model.</td></tr><tr><td><code>config/sanctum.php</code></td><td>Stateful domains (<code>SANCTUM_STATEFUL_DOMAINS</code>), guards checked (<code>web</code>, <code>admin</code>), token expiration.</td></tr><tr><td><code>config/permission.php</code></td><td><code>spatie/laravel-permission</code> configuration (tables, cache).</td></tr></tbody></table>',22)])])}const m=t(a,[["render",c]]);export{p as __pageData,m as default};
